def compute(vars):
    interest_rate_revenue = vars["v1"]
    total_revenue = vars["v2"]

    if total_revenue == 0:
        return None

    percentage = (interest_rate_revenue / total_revenue) * 100

    return {
        "value": percentage,
        "trace": {
            "interest_rate_revenue": interest_rate_revenue,
            "total_revenue": total_revenue,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
